import{_ as o,o as t,c as s,a2 as n}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"Design System & Branding (Desktop)","description":"","frontmatter":{"epic":15,"title":"Design System & Branding (Desktop)","status":"✅ Complete","scope":"desktop","sourceUrl":"https://github.com/sovereignfs/sovereign-edge/blob/main/docs/epics/desktop/design-system.md"},"headers":[],"relativePath":"sovereign-edge/epics/desktop/design-system.md","filePath":"sovereign-edge/epics/desktop/design-system.md"}'),a={name:"sovereign-edge/epics/desktop/design-system.md"};function c(i,e,d,r,l,p){return t(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="epic-design-system-branding-desktop" tabindex="-1">Epic: Design System &amp; Branding (Desktop) <a class="header-anchor" href="#epic-design-system-branding-desktop" aria-label="Permalink to &quot;Epic: Design System &amp; Branding (Desktop)&quot;">​</a></h1><blockquote><p>The desktop equivalent of <a href="./../mobile/design-system.html">Design System &amp; Branding</a> (epic 7) — the same warm cream/clay identity, icon system, and screen redesigns, ported to <code>apps/desktop</code> instead of <code>apps/mobile</code>.</p></blockquote><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Epic 7 ported <code>packages/design-tokens/reference.html</code>&#39;s warm cream/clay visual identity into the mobile app: palette/typography, a curated Lucide icon system, redesigned Chat/Models/Settings/Connectors screens (sections, status pills, a real segmented control, a unified connector-detail screen), and new release assets (app icon + splash screen) using a hand-coded &quot;one gate&quot; mark SVG.</p><p><code>packages/desktop-ui/ThemeProvider.tsx</code> already imports its tokens from the same shared <code>design-tokens</code> package epic 7 repointed at the warm palette — so the base colour/typography layer already reached desktop for free, no task needed for it. Everything past that — icons, section/pill/segmented- control chrome, the unified connector-detail screen, release assets — is still at pre-epic-7 shape on desktop and is this epic&#39;s scope.</p><p><code>reference.html</code> already mocks up every desktop screen this needs (<code>#dscreen-chat</code>, <code>#dscreen-models</code>, <code>#dscreen-connectors</code>, <code>#dscreen-connector-detail</code>, <code>#dscreen-settings</code>), using the identical Lucide-style stroke-icon convention and the same &quot;one gate&quot; mark path data mobile&#39;s <code>Mark.tsx</code> uses — that file is the literal spec here too.</p><p><strong>Versioning note:</strong> unlike mobile&#39;s per-task version-bump convention, desktop&#39;s <code>package.json</code>/<code>Cargo.toml</code>/<code>tauri.conf.json</code> version is bumped only by <code>apps/desktop/scripts/bump-version.mjs</code> (task 14.4&#39;s release tool, which commits/tags/pushes) — ROADMAP.md&#39;s desktop rows already use <code>—</code> instead of a version number for this reason, and this epic&#39;s rows do too.</p><h2 id="tasks" tabindex="-1">Tasks <a class="header-anchor" href="#tasks" aria-label="Permalink to &quot;Tasks&quot;">​</a></h2><h4 id="✅-15-1-—-icon-system" tabindex="-1">✅ 15.1 — Icon system <a class="header-anchor" href="#✅-15-1-—-icon-system" aria-label="Permalink to &quot;✅ 15.1 — Icon system&quot;">​</a></h4><p><strong>Goal:</strong> Give <code>desktop-ui</code> a curated icon set and the app mark, mirroring mobile task 7.4.</p><p><strong>Deliverables:</strong></p><ul><li><code>lucide-react</code> (the DOM equivalent of <code>lucide-react-native</code>, same version 1.31.0) as a dependency of <code>packages/desktop-ui</code>.</li><li>A curated <code>Icon</code> component (<code>packages/desktop-ui/components/Icon.tsx</code>) mirroring mobile&#39;s own <code>&lt;Icon name size color aria-hidden|aria-label&gt;</code> contract and <code>iconSize</code> token binding — <code>color</code> defaults to <code>currentColor</code> here (unlike mobile&#39;s required prop), since the DOM&#39;s SVG renderer, unlike React Native&#39;s, does inherit a surrounding element&#39;s <code>color</code>.</li><li>A <code>Mark</code> component (<code>packages/desktop-ui/components/Mark.tsx</code>) — the same &quot;one gate&quot; path data as <code>apps/mobile/src/design-system/components/ Mark.tsx</code>, for the connector-provenance glyph (used starting task 15.2).</li><li><code>apps/desktop/src/shell/AppShell.tsx</code>&#39;s four sidebar destinations wired to real icons: <code>message-circle</code>/Chat, <code>cpu</code>/Models, <code>settings</code>/Settings, and the <code>Mark</code> itself (not a generic Lucide glyph) for Connectors — matching <code>reference.html</code>&#39;s own desktop sidebar mockup, which ties the connector concept back to the mark&#39;s own motif rather than a generic plug/link icon.</li></ul><p><strong>Dependencies:</strong> None (desktop-ui&#39;s token layer already carries the palette).</p><p><strong>Review checklist:</strong></p><ul><li>✅ <code>pnpm --filter desktop-ui typecheck</code>, <code>pnpm --filter desktop typecheck</code>, <code>pnpm --filter desktop lint</code>, and the full test suite (53 tests, 8 files) all pass.</li><li>✅ Verified in a browser against the app&#39;s own Vite dev server (port 1420, same content a Tauri window loads), both light and dark: all four sidebar icons render at the correct size, the active destination&#39;s accent colour applies to its icon via <code>currentColor</code> with no per-row colour prop needed, and navigating between destinations (confirmed via Connectors) works correctly with the <code>Mark</code> rendering correctly in its active state too.</li></ul><hr><h4 id="✅-15-2-—-chat-screen-icons-provenance-receipts-multiline-composer" tabindex="-1">✅ 15.2 — Chat screen: icons, provenance receipts, multiline composer <a class="header-anchor" href="#✅-15-2-—-chat-screen-icons-provenance-receipts-multiline-composer" aria-label="Permalink to &quot;✅ 15.2 — Chat screen: icons, provenance receipts, multiline composer&quot;">​</a></h4><p><strong>Goal:</strong> Bring <code>ChatScreen.tsx</code> up to <code>reference.html</code>&#39;s <code>#dscreen-chat</code> mockup.</p><p><strong>Deliverables:</strong></p><ul><li>Circular icon send/stop button (a local <code>ComposerButton</code>, matching mobile&#39;s own local-not-shared pattern for this), replacing the full-width text <code>Button</code> — same <code>aria-label</code>s (&quot;Send&quot;/&quot;Stop&quot;) as before, so no existing test needed to change.</li><li><code>ChatBubble</code>&#39;s connector receipt restructured from inline <code>via {name}</code> text inside the bubble to a separate row below it using the new <code>Mark</code> glyph — the same restructure mobile&#39;s task 7.5 made, <code>packages/ desktop-ui/components/ChatBubble.tsx</code> now mirroring <code>apps/mobile/src/ design-system/components/ChatBubble.tsx</code>&#39;s shape.</li><li><code>ModeBar.tsx</code> chips gain icons alongside their existing labels, via a <code>MODE_ICON</code> map identical to mobile&#39;s own (task 7.5) — same icon per concept on both platforms, not a per-platform reinterpretation. (<code>reference.html</code>&#39;s own desktop mockup draws Brainstorm with a pencil icon rather than a lightbulb; mobile&#39;s already-shipped choice was treated as the more deliberate, finalized decision to mirror.)</li><li>Composer becomes a real auto-growing <code>&lt;textarea&gt;</code>, capped at <code>touchTargetMin * 3</code> before scrolling internally — <code>reference.html</code>&#39;s own desktop mockup uses a static <code>rows=&quot;2&quot;</code> textarea with no growth behavior at all, but mobile&#39;s already-proven &quot;grows then caps&quot; composer was judged the more faithful thing to mirror; growth is JS-driven (<code>scrollHeight</code> measured into an explicit <code>height</code> on every keystroke), since a plain HTML <code>&lt;textarea&gt;</code> does not do this on its own the way RN&#39;s <code>TextInput</code> does.</li><li>The risky-model warning banner also gains an <code>alert-triangle</code> icon, matching mobile&#39;s own iconified warning banner.</li></ul><p><strong>Dependencies:</strong> Task 15.1.</p><p><strong>Review checklist:</strong></p><ul><li>✅ <code>pnpm --filter desktop-ui typecheck</code>, <code>pnpm --filter desktop typecheck</code>, <code>pnpm --filter desktop lint</code>, and the full test suite (53 tests, 8 files) all pass unchanged — every existing query in <code>ChatScreen.test.tsx</code>/<code>ModeBar.test.tsx</code> targets <code>role</code>/<code>aria-label</code>, none of which changed, so no test needed editing for this task.</li><li>✅ Verified in a browser against the app&#39;s own Vite dev server, both light and dark: mode chip icons, the circular send button, and the connector receipt&#39;s <code>Mark</code> glyph all render correctly. The composer&#39;s grow-then-cap-then-scroll behavior was verified by scripting real input events into the <code>&lt;textarea&gt;</code> (bypassing its <code>disabled</code> state, which needs a live Tauri backend/loaded model this browser-only preview doesn&#39;t have) and reading back <code>scrollHeight</code>/<code>clientHeight</code>: growth confirmed up to the cap, then <code>scrollHeight</code> (214px) exceeding <code>clientHeight</code> (130px ≈ the 132px cap) confirmed the internal-scroll hand-off engages correctly past it.</li><li>⚠️ The composer&#39;s real <code>disabled</code>/model-loaded gating and the actual send→reply round trip were not exercised end-to-end — this browser-only Vite preview has no Tauri IPC backend behind it (no native window available to drive interactively in this environment). Covered instead by the existing, unchanged <code>ChatScreen.test.tsx</code> suite, which drives the real <code>send()</code>/<code>stop()</code> handlers against a mocked <code>lib/tauri</code> backend.</li></ul><hr><h4 id="✅-15-3-—-models-screen-sections-progress-bar-fit-badge" tabindex="-1">✅ 15.3 — Models screen: sections, progress bar, fit badge <a class="header-anchor" href="#✅-15-3-—-models-screen-sections-progress-bar-fit-badge" aria-label="Permalink to &quot;✅ 15.3 — Models screen: sections, progress bar, fit badge&quot;">​</a></h4><p><strong>Goal:</strong> Bring <code>ModelsScreen.tsx</code> up to <code>reference.html</code>&#39;s <code>#dscreen-models</code> mockup.</p><p><strong>Deliverables:</strong></p><ul><li>Installed/Available section split, using a new <code>SectionLabel</code> component (<code>packages/desktop-ui</code>) — same uppercase-via-JS treatment as mobile&#39;s own <code>SectionLabel</code> (task 7.6), not <code>reference.html</code>&#39;s literal sentence-case CSS, for the same &quot;mirror mobile&#39;s shipped decision&quot; reasoning task 15.2 already used for icon choices.</li><li>A new <code>ProgressBar</code> component (<code>role=&quot;progressbar&quot;</code>, <code>aria-value*</code>) renders during an active download, replacing the inline percentage/byte- count text — the byte-count stays in the subtitle since the badge and bar already cover the percentage.</li><li>A new <code>FitBadge</code> component (good/tight/bad/neutral, same variant name and colour mapping as mobile&#39;s own — <code>packages/desktop-ui</code> and <code>apps/mobile/src/design-system</code> now agree on this vocabulary) replaces the mono-coloured accessory text everywhere: install state (<code>Download</code>/ <code>Installed</code>/<code>In use</code>), transfer state (percentage/<code>Verifying</code>/<code>Retry</code>), and refusal (<code>Too large</code>, colour-coded red rather than an accent-styled &quot;download anyway&quot;). The badge now names a <em>status</em>; the action it implies moved into the subtitle (e.g. &quot;click to download anyway&quot;).</li><li><code>ListItem</code> gained an optional <code>footer</code> slot (content below the subtitle, in the same column) so the progress bar can render without overlapping the badge — same addition mobile&#39;s own <code>ListItem</code> got in task 7.6.</li></ul><p><strong>Dependencies:</strong> Task 15.1.</p><p><strong>Review checklist:</strong></p><ul><li>✅ <code>pnpm --filter desktop-ui typecheck</code>, <code>pnpm --filter desktop typecheck</code>, <code>pnpm --filter desktop lint</code>, and the full test suite (54 tests, 8 files) all pass. Tests that asserted on the old uppercase mono labels (<code>DOWNLOAD</code>, <code>IN USE</code>, <code>INSTALLED</code>, <code>RETRY</code>, <code>CANCEL</code>) switched to the new sentence-case badge text; the <code>CANCEL</code> accessory (now a live percentage badge) is asserted via the same placeholder (<code>…</code>) the subtitle&#39;s own unknown-total fallback already used; one new test covers the Installed/Available section split.</li><li>✅ Verified visually against the app&#39;s own Vite dev server, both light and dark: since this browser-only preview has no Tauri backend behind it (<code>listModels()</code>/<code>activeModelId()</code> reject with nothing to render), verification used temporarily seeded fixture data covering all four badge variants and an in-progress download at once (installed/active, downloading at 67%, available/comfortable, available/unsupported) — confirmed section split, progress bar fill, and all four <code>FitBadge</code> colours render correctly in both schemes, then reverted the fixture data before finalizing.</li></ul><hr><h4 id="✅-15-4-—-settings-segmented-control-connectors-restructure" tabindex="-1">✅ 15.4 — Settings segmented control + Connectors restructure <a class="header-anchor" href="#✅-15-4-—-settings-segmented-control-connectors-restructure" aria-label="Permalink to &quot;✅ 15.4 — Settings segmented control + Connectors restructure&quot;">​</a></h4><p><strong>Goal:</strong> Fix the same two structural gaps mobile task 7.7 fixed: the theme picker&#39;s plain-button <code>role=&quot;radiogroup&quot;</code> (Settings and Search setup both use this pattern), and Connectors having no section headers or per-connector detail screen.</p><p><strong>Deliverables:</strong></p><ul><li>A new <code>SegmentedControl</code> component (<code>packages/desktop-ui</code>), replacing the plain-button radiogroup in both <code>SettingsScreen.tsx</code>&#39;s theme picker and the Search provider picker. <code>SettingsScreen.tsx</code> also gained <code>SectionLabel</code>s (Appearance/Privacy/About) and a chevron on its Connectors row, mirroring the same section treatment task 15.3 gave Models.</li><li>Connectors gains section headers (<code>SectionLabel</code>: Search/Calendar/ Installed — desktop has no Device tier, unlike mobile) and status <code>FitBadge</code>s (<code>Allowed</code>/<code>Not granted</code>/<code>Not set up</code>), replacing the flat <code>Toggle</code>-per-row list with rows that navigate into an inline connector detail view (grant/revoke, and — for store-installed connectors only — remove) built inside <code>ConnectorsScreen.tsx</code> itself, using the same list/detail-toggle-in-one-file pattern <code>ConnectorStoreScreen.tsx</code> already established, rather than a new <code>AppShell</code> destination.</li><li><code>SearchSetupScreen.tsx</code> folded into <code>ConnectorsScreen.tsx</code>&#39;s own <code>SearchDetail</code> sub-view (its own file and test deleted); Search keeps its &quot;reconfigure, no remove&quot; treatment since it&#39;s built into the app, not store-installed.</li><li>Calendar connectors keep task 10.2&#39;s real-OS-permission gate: granting calls <code>requestCalendarAccess()</code> first and only proceeds to <code>setConnectorGranted</code> on success; revoking never re-requests OS access.</li><li><strong>Scope reduction, stated explicitly rather than left implicit:</strong> unlike mobile&#39;s manifest-based connectors, desktop&#39;s <code>ConnectorStatus</code> DTO is <code>{ id, name, granted }</code> only — no scope/origin data crosses the IPC boundary for installed connectors. Desktop&#39;s connector detail views therefore have no &quot;Reaches&quot; section (mobile&#39;s does); this is a real backend API gap the frontend can&#39;t paper over, not an oversight, and is left for a future task if scope display is wanted here.</li></ul><p><strong>Dependencies:</strong> Tasks 15.1, 15.3 (reuses <code>SectionLabel</code>/<code>FitBadge</code>).</p><p><strong>Review checklist:</strong></p><ul><li>✅ <code>pnpm --filter desktop-ui typecheck</code>, <code>pnpm --filter desktop typecheck</code>, <code>pnpm --filter desktop lint</code>, and the full test suite (48 tests, 7 files) all pass — <code>SearchSetupScreen.test.tsx</code>&#39;s cases moved into <code>ConnectorsScreen.test.tsx</code> (12 tests covering empty/configured Search, section pills, store-installed Remove, and all three Calendar OS-permission-gate cases), <code>SettingsScreen.test.tsx</code>&#39;s 7 existing tests pass unchanged against the new <code>SegmentedControl</code> markup.</li><li>✅ Verified visually against the app&#39;s own Vite dev server, both light and dark: since this browser-only preview has no Tauri backend behind it (<code>listConnectors()</code> never resolves), verification used temporarily seeded fixture data (four connectors spanning Search/Calendar/Installed, granted and not-granted) — confirmed the sectioned list (pills, chevrons), the Search detail view (Allowed pill, Revoke, provider <code>SegmentedControl</code>, Instance URL field, Save), the store-installed detail view (Revoke + Remove), and the not-granted Calendar detail view (neutral &quot;Not granted&quot; pill, accent &quot;Grant access&quot; button, no Remove) all render correctly in both colour schemes — then reverted the fixture data before finalizing, same as task 15.3.</li></ul><hr><h4 id="✅-15-5-—-release-assets-app-icon-splash-window" tabindex="-1">✅ 15.5 — Release assets: app icon + splash window <a class="header-anchor" href="#✅-15-5-—-release-assets-app-icon-splash-window" aria-label="Permalink to &quot;✅ 15.5 — Release assets: app icon + splash window&quot;">​</a></h4><blockquote><p><strong>The splash window described here no longer exists.</strong> It shipped as described, then was removed wholesale in <code>c13ddf1</code> — <code>public/ splashscreen.html</code>, the <code>splashscreen</code> window in <code>tauri.conf.json</code>, the <code>show_main_window</code> command (with its <code>build.rs</code> <code>COMMANDS</code> entry and <code>capabilities/default.json</code> permission), and <code>App.tsx</code>&#39;s first-mount <code>useEffect</code> are all gone, and <code>main</code> no longer starts <code>visible: false</code>. The reason is the risk the last checklist item below flagged and could not test here: the hand-off got stuck on the splash indefinitely on a real Tauri runtime. Deleting it was judged simpler than debugging it, and opening straight to the main window matches the reference product. That commit also added the <code>core:window:allow-start-dragging</code> capability the custom titlebar&#39;s drag region had always been missing.</p><p>The task stays ✅ because both halves did ship and were reviewed; the icon half is still live. Nothing here is a regression to fix — this note exists so the deliverables below aren&#39;t read as a description of the current code.</p></blockquote><p><strong>Goal:</strong> Replace the stock Tauri template icon with the &quot;one gate&quot; mark, and add a real splash window covering the gap before the app&#39;s first paint.</p><p><strong>Deliverables:</strong></p><ul><li><code>apps/desktop/src-tauri/icons/*</code> regenerated via <code>pnpm tauri icon ../mobile/assets/icon.png</code> — the workflow <code>apps/desktop/AGENTS.md</code> already documents. That command&#39;s default output also includes iOS/ Android/Windows-Store-tile assets this desktop-only bundle doesn&#39;t use (not referenced by <code>tauri.conf.json</code>&#39;s <code>bundle.icon</code> or <code>bundle.targets</code>, and absent from the original <code>tauri init</code> scaffold) — deleted after generation rather than committed as unused cruft; only the same 7 files the scaffold originally tracked were kept, now regenerated with the mark.</li><li>A second <code>tauri.conf.json</code> window (<code>splashscreen</code>: transparent, undecorated, centered, <code>skipTaskbar</code>) showing a static <code>apps/desktop/public/splashscreen.html</code> with the inline mark SVG and a <code>prefers-color-scheme</code> media query, using the same light/dark colour pairs mobile&#39;s splash screen used (<code>grey50</code>/<code>clay700</code> light, <code>grey950</code>/<code>clay300</code> dark) — hardcoded in the HTML rather than read from CSS vars, since this window never mounts <code>ThemeProvider</code> or any app JS. Lives in <code>public/</code> (Vite&#39;s static-asset convention) rather than a page Vite processes, so it needs no bundler entry of its own and resolves identically in dev (served at <code>/splashscreen.html</code> by the same Vite dev server) and in a production build (copied into <code>dist/</code> verbatim).</li><li><code>main</code> window starts <code>&quot;visible&quot;: false</code>; a new <code>show_main_window</code> Tauri command (registered in <code>lib.rs</code>&#39;s <code>invoke_handler!</code> <em>and</em> <code>build.rs</code>&#39;s <code>COMMANDS</code> list — the latter is what actually makes the <code>allow-show-main-window</code> permission this command&#39;s <code>capabilities/ default.json</code> entry names exist at all; missing it fails the Rust build itself with &quot;Permission ... not found&quot;, not a silent gap, per <code>build.rs</code>&#39;s own doc comment) that <code>App.tsx</code> invokes once, in a first-mount <code>useEffect</code>, to show <code>main</code> and close <code>splashscreen</code>. Looked up by label via <code>get_webview_window</code>, which returns <code>None</code> rather than panicking on a missing label, so React 19 <code>StrictMode</code>&#39;s dev-only double effect invocation (a second, harmless call after <code>splashscreen</code> is already closed) is not a bug to guard against.</li></ul><p><strong>Dependencies:</strong> None (independent of 15.1–15.4, same as mobile 7.8 was independent of 7.4–7.7).</p><p><strong>Review checklist:</strong></p><ul><li>✅ <code>pnpm --filter desktop typecheck</code>, <code>pnpm --filter desktop lint</code>, and the full test suite (48 tests, 7 files) pass. On the Rust side: <code>cargo check</code>, <code>cargo test --lib</code> (150 tests) and <code>cargo test</code> (every target), <code>cargo clippy --all-targets -- -D warnings</code>, and <code>cargo fmt --check</code> all clean in <code>src-tauri/</code>.</li><li>✅ Regenerated <code>icon.png</code> visually confirmed against the prior stock Tauri gradient placeholder — now the &quot;one gate&quot; mark on a cream background, matching <code>apps/mobile/assets/icon.png</code> exactly (same source file).</li><li>✅ <code>splashscreen.html</code> verified directly in a browser (no Tauri backend needed for a static file) in both colour schemes: light shows the clay mark on a cream background, dark shows the lighter clay tint on a near-black background, matching mobile&#39;s own splash colour pairs.</li><li>⚠️ The actual windowed hand-off — <code>main</code> starting hidden, the splash window appearing first, and <code>show_main_window</code> closing it after React&#39;s first paint — was not exercised end-to-end in this environment (no Tauri runtime/native window available here, only the browser-only Vite preview used for every other visual check in this epic). Covered instead by: <code>cargo check</code>/<code>clippy</code>/<code>fmt</code> confirming the Rust side (window lookup-by-label, command registration, capability wiring) is correct: and a manual review of <code>tauri.conf.json</code>&#39;s window config against Tauri v2&#39;s own schema (<code>src-tauri/gen/schemas/*.json</code>), which <code>cargo check</code> already validates by deserializing it at build time. A real <code>pnpm tauri dev</code> / <code>pnpm tauri build</code> launch to watch the hand-off with your own eyes is the one verification step this task couldn&#39;t do here. <strong>This is exactly where it broke</strong> — that launch, once someone did it, showed the app stuck on the splash; see the note under this task&#39;s heading. A worked example of why &quot;the Rust compiles and the config validates&quot; is not the same claim as &quot;the window hand-off works.&quot;</li></ul><h2 id="related-docs" tabindex="-1">Related Docs <a class="header-anchor" href="#related-docs" aria-label="Permalink to &quot;Related Docs&quot;">​</a></h2><ul><li><a href="./../mobile/design-system.html">Mobile Design System &amp; Branding</a> (epic 7 — the completed mobile counterpart this epic mirrors)</li><li><a href="./../../../packages/design-tokens/reference.html">packages/design-tokens/reference.html</a></li></ul>',50)])])}const g=o(a,[["render",c]]);export{u as __pageData,g as default};
